trait Logger { fn log(&self, msg: &str); }

struct NullLogger;
impl Logger for NullLogger {
    fn log(&self, _msg: &str) {}          // one line of nothing
}

struct Service<L: Logger> { logger: L }
impl<L: Logger> Service<L> {
    fn run(&self) { self.logger.log("running"); }   // no Option, no branch
}
